def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = 0
    my_defects = 0
    opp_coops = 0
    cc = 0
    cd = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        else:
            opp_coops += 1
        if m == 'D':
            my_defects += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1

    last_m, last_o = history[-1]

    # Very early: establish cooperation, retaliate immediately to defection.
    if n < 3:
        if last_o == 'D':
            return 'D'
        return 'C'

    # If opponent has never defected, keep cooperating; defect only at the
    # very end (last round) to grab the extra payoff.
    if opp_defects == 0:
        if n == 100:
            return 'D'
        return 'C'

    # Endgame: if opponent has been a reliable cooperator, keep cooperating
    # almost to the end, then defect on the final round.
    if n >= 95:
        if opp_defects <= 2:
            if n == 100:
                return 'D'
            return 'C'
        if last_o == 'D':
            return 'D'
        return 'C'

    # Immediate retaliation: if opponent just defected and we cooperated,
    # defect back (Tit-for-Tat) to avoid being exploited.
    if last_o == 'D':
        if last_m == 'C':
            # If opponent is mostly cooperative, forgive quickly once.
            if opp_defects <= max(1, n // 8) and n < 60:
                if n >= 2 and history[-2][1] == 'D':
                    return 'D'
                return 'C'
            return 'D'
        # Both defected: try to break the DD cycle if opponent is mostly cooperative.
        if opp_coops * 2 >= n and n > 15:
            return 'C'
        # Otherwise stay in defection mode.
        return 'D'

    # Opponent cooperated last round.
    if last_m == 'D':
        # We defected and they cooperated: return to cooperation to preserve
        # mutually beneficial CC, unless opponent defects a lot overall.
        if opp_defects * 3 > n:
            return 'D'
        return 'C'

    # Both cooperated: stay cooperative, but occasionally probe an overly
    # cooperative opponent to catch exploitable weaklings, and punish
    # frequent defectors occasionally.
    if opp_defects * 4 > n:
        # Opponent defects moderately often; use occasional defection to
        # discourage them without triggering long punishment cycles.
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent is fairly cooperative: mostly cooperate, rare probes.
    if n > 20 and rng.random() < 0.03:
        return 'D'
    return 'C'
